SELECT uniqExact(person_id) AS Total FROM events WHERE (event IN ('studio_screen_viewed','native_app_opened','native_screen_viewed','native_app_active','native_project_created','native_media_imported','native_export_completed','native_action_finished') OR event='product_action_completed') AND properties.surface='macos' AND (properties.environment = 'production' AND properties.product = 'studio') AND {filters}
